declarations.code:
friend constexpr void iter_swap(const /*iterator*/ &x, const /*iterator*/ &y)

    noexcept(/*see below*/)

    requires std::indirectly_swappable<ranges::iterator_t<Base>>;

intro:
Swaps the objects pointed to by two underlying arrays of iterators (denoted as current_).

Equivalent to:

for (std::size_t i{}; i != N; ++i)
{
    std::ranges::iter_swap(x.current_[i], y.current_[i]);
}

The behavior is undefined if before the operation none of the iterators in x.current_ is equal to an iterator in y.current_.

This function  is not visible to ordinary unqualified or qualified lookup, and can only be found by argument-dependent lookup when adjacent_view::iterator<Const> is an associated class of the arguments.

examples.code:
#include <ranges>
#include <iterator>
#include <tuple>
#include <cassert>
#include <type_traits>
#include <utility>
template <class I, class S> void inspectSentinel(I position, S sentinel) {
    if constexpr (requires { sentinel.base(); })
        (void)sentinel.base();
    if constexpr (requires { sentinel - position; })
        assert(sentinel - position > 0);
    if constexpr (requires { position - sentinel; })
        assert(position - sentinel < 0);
}
int main() {
    [[maybe_unused]] int values[]{1, 3, 5, 7};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}};
    auto base =
        std::ranges::subrange(std::counted_iterator(values, 4), std::default_sentinel);
    auto nestedBase =
        std::ranges::subrange(std::counted_iterator(nested, 2), std::default_sentinel);
    auto pairBase =
        std::ranges::subrange(std::counted_iterator(pairs, 2), std::default_sentinel);
    (void)nestedBase;
    (void)pairBase;
    auto view = std::views::adjacent<2>(base);
    auto first = view.begin();
    auto sentinel = view.end();
    assert(first != sentinel);
    inspectSentinel(first, sentinel);
    auto copy = first;
    assert(copy == first);
    (void)*first;
    ++copy;
    assert(copy != first);
    std::ranges::iter_swap(first, copy);

    assert(std::ranges::distance(view) > 0);
    // A non-common base keeps a distinct sentinel type and exercises its constructor
    // and comparison.
}
